<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> header </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &quot;Content-Disposition: attachment; filename*=UTF-8&#39;&#39;&quot;</span><span style="color:#D73A49;"> +</span><span style="color:#6F42C1;"> encodeRFC5987ValueChars</span><span style="color:#24292E;">(fileName);</span></span>
